inline const TextDeltaGroup* find_text_deltas(TextSelection selection) noexcept {
    if (!selection) return nullptr;
    for (const auto& group : text_delta_groups)
        if (group.family == selection.family && group.language == selection.language) return &group;
    return nullptr;
}
